import { fn } from 'jest-mock';

type FunctionInvokeResponse = {
  data: any;
  error: any;
};

const defaultInvokeResponse = (): FunctionInvokeResponse => ({
  data: {
    success: true,
  },
  error: null,
});

export const invokeFunction = fn(async () => defaultInvokeResponse());

export const createFunctionsMock = () => ({
  invoke: invokeFunction,
});

export const __setInvokeFunctionResponse = (response: FunctionInvokeResponse) => {
  invokeFunction.mockResolvedValue(response);
};

export const resetFunctionsMock = () => {
  invokeFunction.mockReset();
  invokeFunction.mockResolvedValue(defaultInvokeResponse());
};

resetFunctionsMock();

import { fn } from 'jest-mock';
import { createFunctionsMock, resetFunctionsMock } from './supabase/functions';

type MockResponse = {
  data: any;
  error: any;
};

type TableOperation = 'select' | 'insert' | 'update' | 'upsert' | 'delete';

const tableOperationResponses = new Map<string, Partial<Record<TableOperation, MockResponse>>>();
let rpcResponse: MockResponse = { data: null, error: null };

const cloneResponse = (response: MockResponse): MockResponse => ({
  data: response.data,
  error: response.error,
});

const defaultResponseFor = (operation: TableOperation, expectSingle: boolean): MockResponse => {
  if (expectSingle) {
    return { data: { id: 'mock-row-id', value: true }, error: null };
  }

  if (operation === 'insert' || operation === 'update' || operation === 'upsert') {
    return { data: [{ id: 'mock-row-id' }], error: null };
  }

  return { data: [], error: null };
};

const resolveTableResponse = (
  table: string,
  operation: TableOperation,
  expectSingle: boolean
): MockResponse => {
  const tableOverrides = tableOperationResponses.get(table);
  const operationOverride = tableOverrides?.[operation];
  const base = operationOverride ?? defaultResponseFor(operation, expectSingle);

  if (expectSingle && Array.isArray(base.data)) {
    return {
      data: base.data[0] ?? null,
      error: base.error,
    };
  }

  return cloneResponse(base);
};

const makeQueryBuilder = (table: string) => {
  let currentOperation: TableOperation = 'select';

  const builder: any = {};

  const setOperation = (operation: TableOperation) => {
    currentOperation = operation;
    return builder;
  };

  const passthrough = () => builder;

  builder.select = fn((_columns?: string) => setOperation('select'));
  builder.insert = fn((_values?: any) => setOperation('insert'));
  builder.update = fn((_values?: any) => setOperation('update'));
  builder.upsert = fn((_values?: any) => setOperation('upsert'));
  builder.delete = fn(() => setOperation('delete'));

  builder.eq = fn(passthrough);
  builder.neq = fn(passthrough);
  builder.in = fn(passthrough);
  builder.or = fn(passthrough);
  builder.and = fn(passthrough);
  builder.not = fn(passthrough);
  builder.is = fn(passthrough);
  builder.gte = fn(passthrough);
  builder.gt = fn(passthrough);
  builder.lte = fn(passthrough);
  builder.lt = fn(passthrough);
  builder.ilike = fn(passthrough);
  builder.like = fn(passthrough);
  builder.contains = fn(passthrough);
  builder.overlaps = fn(passthrough);
  builder.match = fn(passthrough);
  builder.order = fn(passthrough);
  builder.limit = fn(passthrough);
  builder.range = fn(passthrough);
  builder.filter = fn(passthrough);

  builder.single = fn(async () => resolveTableResponse(table, currentOperation, true));
  builder.maybeSingle = fn(async () => {
    const response = resolveTableResponse(table, currentOperation, true);
    return {
      data: response.data ?? null,
      error: response.error,
    };
  });

  builder.then = (onFulfilled: any, onRejected: any) =>
    Promise.resolve(resolveTableResponse(table, currentOperation, false)).then(onFulfilled, onRejected);

  return builder;
};

const makeChannel = () => {
  const channel: any = {};
  channel.on = fn(() => channel);
  channel.subscribe = fn(() => channel);
  channel.unsubscribe = fn(async () => ({ error: null }));
  channel.send = fn(async () => ({ error: null }));
  channel.track = fn(async () => ({ error: null }));
  return channel;
};

export const supabase = {
  auth: {
    getUser: fn(async () => ({ data: { user: null }, error: null })),
    getSession: fn(async () => ({ data: { session: null }, error: null })),
    signUp: fn(async () => ({ data: { user: null, session: null }, error: null })),
    signInWithPassword: fn(async () => ({ data: { user: null, session: null }, error: null })),
    signOut: fn(async () => ({ error: null })),
  },
  from: fn((table: string) => makeQueryBuilder(table)),
  rpc: fn(async () => cloneResponse(rpcResponse)),
  functions: createFunctionsMock(),
  channel: fn(() => makeChannel()),
  removeChannel: fn(async () => ({ error: null })),
  removeAllChannels: fn(async () => ({ error: null })),
};

export const __setSupabaseTableResponse = (
  table: string,
  operation: TableOperation,
  response: MockResponse
) => {
  const existing = tableOperationResponses.get(table) ?? {};
  existing[operation] = response;
  tableOperationResponses.set(table, existing);
};

export const __setSupabaseRpcResponse = (response: MockResponse) => {
  rpcResponse = response;
};

export const __resetSupabaseMocks = () => {
  tableOperationResponses.clear();
  rpcResponse = { data: null, error: null };
  resetFunctionsMock();

  supabase.auth.getUser.mockReset();
  supabase.auth.getSession.mockReset();
  supabase.auth.signUp.mockReset();
  supabase.auth.signInWithPassword.mockReset();
  supabase.auth.signOut.mockReset();
  supabase.from.mockClear();
  supabase.rpc.mockReset();
  supabase.channel.mockClear();
  supabase.removeChannel.mockReset();
  supabase.removeAllChannels.mockReset();

  supabase.auth.getUser.mockResolvedValue({ data: { user: null }, error: null });
  supabase.auth.getSession.mockResolvedValue({ data: { session: null }, error: null });
  supabase.auth.signUp.mockResolvedValue({ data: { user: null, session: null }, error: null });
  supabase.auth.signInWithPassword.mockResolvedValue({
    data: { user: null, session: null },
    error: null,
  });
  supabase.auth.signOut.mockResolvedValue({ error: null });
  supabase.rpc.mockResolvedValue({ data: null, error: null });
  supabase.removeChannel.mockResolvedValue({ error: null });
  supabase.removeAllChannels.mockResolvedValue({ error: null });
};

__resetSupabaseMocks();

import '@testing-library/jest-native/extend-expect';
import * as dotenv from 'dotenv';
import * as path from 'path';

// Load environment variables for testing.
// Prefer staging env when running Supabase E2E.
dotenv.config({ path: path.join(__dirname, '.env.staging'), quiet: true });
dotenv.config({ path: path.join(__dirname, '.env'), quiet: true });

// Make TypeScript happy in this test setup file (jest is a runtime global)
declare const jest: any;

// Silence native warnings that commonly appear in test runs
// Note: Do NOT enable fake timers globally.
// Many @testing-library/react-native helpers (e.g. waitFor) rely on real timers.
// Individual tests can opt-in with `jest.useFakeTimers()` when needed.

// Mock native AsyncStorage for tests
jest.mock('@react-native-async-storage/async-storage', () =>
	require('@react-native-async-storage/async-storage/jest/async-storage-mock')
);

// Mock native expo modules that expect a device environment
(globalThis as any).jest?.mock && jest.mock('expo-status-bar', () => ({ StatusBar: 'StatusBar' }));

// Provide lightweight mocks for native-base components used in unit tests so
// tests do not depend on the full NativeBase runtime or theme system.
if ((globalThis as any).jest?.mock) {
	jest.mock('native-base', () => {
		const React = require('react');

		const NativeBaseProvider = ({ children }: any) => React.createElement(React.Fragment, null, children);
		const Button = (props: any) => React.createElement('button', props as any, props.children);

		return {
			__esModule: true,
			NativeBaseProvider,
			Button,
		};
	});
}

if ((globalThis as any).jest?.mock) {
	jest.mock('@stripe/stripe-react-native', () => {
		const { fn } = require('jest-mock');
		const retrieveSetupIntent = fn(async () => ({
			setupIntent: { paymentMethodId: 'pm_test_default' },
			error: null,
		}));
		return {
			__esModule: true,
			useStripe: fn(() => ({
				retrieveSetupIntent,
			})),
			initPaymentSheet: fn(async () => ({ error: null })),
			presentPaymentSheet: fn(async () => ({ error: null })),
			PaymentSheetError: {},
		};
	});
}

// Provide dummy Supabase env vars for unit tests so creating the client doesn't throw
// When RUN_SUPABASE_E2E=true, these will be loaded from .env file
process.env.EXPO_PUBLIC_SUPABASE_URL = process.env.EXPO_PUBLIC_SUPABASE_URL || process.env.SUPABASE_URL || 'http://localhost';
process.env.EXPO_PUBLIC_SUPABASE_ANON_KEY = process.env.EXPO_PUBLIC_SUPABASE_ANON_KEY || process.env.SUPABASE_ANON_KEY || 'anon-key';

// By default, prevent tests from making real Supabase/network calls.
// Opt-in to real Supabase E2E by setting `RUN_SUPABASE_E2E=true`.
const runSupabaseE2E = process.env.RUN_SUPABASE_E2E === 'true';

const delay = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

// Network-backed E2E tests can intermittently fail with transient socket resets.
// Retry only short-lived transport errors to reduce flakiness without masking logic failures.
if (runSupabaseE2E && typeof globalThis.fetch === 'function') {
	const originalFetch = globalThis.fetch.bind(globalThis);

	globalThis.fetch = async (...args: Parameters<typeof fetch>): Promise<Response> => {
		let lastError: unknown;

		for (let attempt = 1; attempt <= 3; attempt += 1) {
			try {
				const response = await originalFetch(...args);

				if ([502, 503, 504].includes(response.status) && attempt < 3) {
					await delay(attempt * 200);
					continue;
				}

				return response;
			} catch (error) {
				lastError = error;
				const message = error instanceof Error ? error.message : String(error);
				const isTransient = /ECONNRESET|ETIMEDOUT|EAI_AGAIN|fetch failed|network/i.test(message);

				if (!isTransient || attempt === 3) {
					throw error;
				}

				await delay(attempt * 200);
			}
		}

		throw lastError instanceof Error ? lastError : new Error('Fetch failed after retries');
	};
}

if (!runSupabaseE2E && (globalThis as any).jest?.mock) {
	jest.mock('@/config/supabase', () => require('./src/__mocks__/supabase'));

	beforeEach(() => {
		const { __resetSupabaseMocks } = require('./src/__mocks__/supabase');
		if (typeof __resetSupabaseMocks === 'function') {
			__resetSupabaseMocks();
		}
	});

	jest.mock('@supabase/supabase-js', () => {
		const { fn } = require('jest-mock');

		const makeQueryBuilder = () => {
			const builder: any = {};
			// Make the query builder awaitable (Supabase queries are promise-like).
			builder.then = (onFulfilled: any, onRejected: any) =>
				Promise.resolve({ data: [], error: null }).then(onFulfilled, onRejected);

			builder.select = fn(() => builder);
			builder.insert = fn(() => builder);
			builder.update = fn(() => builder);
			builder.upsert = fn(() => builder);
			builder.delete = fn(() => builder);
			builder.eq = fn(() => builder);
			builder.neq = fn(() => builder);
			builder.or = fn(() => builder);
			builder.in = fn(() => builder);
			builder.ilike = fn(() => builder);
			builder.gte = fn(() => builder);
			builder.lte = fn(() => builder);
			builder.is = fn(() => builder);
			builder.not = fn(() => builder);
			builder.order = fn(() => builder);
			builder.limit = fn(async () => ({ data: [], error: null }));
			builder.single = fn(async () => ({ data: null, error: null }));
			builder.maybeSingle = fn(async () => ({ data: null, error: null }));
			return builder;
		};

		const makeChannel = () => {
			const channel: any = {};
			channel.on = fn(() => channel);
			channel.subscribe = fn(() => ({ unsubscribe: fn() }));
			channel.unsubscribe = fn();
			channel.track = fn(async () => ({ error: null }));
			channel.send = fn(async () => ({ error: null }));
			return channel;
		};

		const mockClient = {
			auth: {
				getUser: fn(async () => ({ data: { user: null }, error: null })),
				getSession: fn(async () => ({ data: { session: null }, error: null })),
				signUp: fn(async () => ({ data: { user: null, session: null }, error: null })),
				signInWithPassword: fn(async () => ({ data: { user: null, session: null }, error: null })),
				signOut: fn(async () => ({ error: null })),
			},
			from: fn(() => makeQueryBuilder()),
			rpc: fn(async () => ({ data: null, error: null })),
			functions: {
				invoke: fn(async () => ({ data: { success: true }, error: null })),
			},
			channel: fn(() => makeChannel()),
			removeChannel: fn(async () => ({ error: null })),
		};

		const createClient = fn(() => mockClient);
		class SupabaseClient {}

		return {
			__esModule: true,
			createClient,
			SupabaseClient,
		};
	});
}

// Mock the testSupabase util so we don't make network calls in unit tests
if ((globalThis as any).jest?.mock) {
	// jest.mock factories must not reference out-of-scope variables (Jest's runtime rule).
	// Return a simple async function instead of `jest.fn(...)` to avoid the "Invalid variable access: jest" error.
	jest.mock('./src/utils/testSupabase', () => ({
		testSupabaseConnection: async () => true,
	}));
}

import { beforeEach, describe, expect, it, jest } from '@jest/globals';
import { uploadListingImages } from '../listing';
import { supabase } from '../../config/supabase';
import { uploadImage, deleteImage } from '../supabase/storage';

jest.mock('../../config/supabase');
jest.mock('../subscription', () => ({
  getSubscriptionSummary: jest.fn(),
  getSubscriptionStatusString: jest.fn(),
}));
jest.mock('../analytics', () => ({
  trackEvent: jest.fn(),
}));
jest.mock('../supabase/storage', () => ({
  uploadImage: jest.fn(),
  deleteImage: jest.fn(),
}));

const mockSupabase = supabase as jest.Mocked<typeof supabase>;
const mockUploadImage = uploadImage as jest.MockedFunction<typeof uploadImage>;
const mockDeleteImage = deleteImage as jest.MockedFunction<typeof deleteImage>;

describe('uploadListingImages', () => {
  beforeEach(() => {
    jest.clearAllMocks();

    mockSupabase.from = jest.fn((table: string) => {
      if (table === 'admin_config') {
        return {
          select: jest.fn().mockReturnValue({
            eq: jest.fn().mockReturnValue({
              single: jest.fn().mockResolvedValue({
                data: { value: false },
                error: null,
              }),
            }),
          }),
        } as any;
      }

      return {
        insert: jest.fn().mockReturnValue({
          select: jest.fn().mockReturnValue({
            single: jest.fn().mockResolvedValue({
              data: { id: 'img-1' },
              error: null,
            }),
          }),
        }),
      } as any;
    });

    mockSupabase.functions = {
      invoke: jest.fn().mockResolvedValue({
        data: {
          success: true,
          decision: 'approved',
          flagged: false,
          categories: [],
          confidence: 0.1,
        },
        error: null,
      }),
    } as any;
  });

  it('uploads successfully using preferred seller/listing path', async () => {
    mockUploadImage.mockResolvedValue({
      url: 'https://example.com/item-images/seller-1/listing-1/0.jpg',
      path: 'seller-1/listing-1/0.jpg',
      error: null,
    });

    const result = await uploadListingImages('listing-1', 'seller-1', ['file:///photo.jpg']);

    expect(mockUploadImage).toHaveBeenCalledTimes(1);
    expect(mockUploadImage).toHaveBeenCalledWith(
      'item-images',
      'seller-1/listing-1/0.jpg',
      'file:///photo.jpg',
      { upsert: true }
    );
    expect(result).toEqual([
      {
        url: 'https://example.com/item-images/seller-1/listing-1/0.jpg',
        display_order: 0,
      },
    ]);
  });

  it('falls back to legacy listing-only path when preferred path is blocked by RLS', async () => {
    const rlsError = new Error('new row violates row-level security policy');
    rlsError.name = 'StorageApiError';

    mockUploadImage
      .mockResolvedValueOnce({
        url: null,
        path: null,
        error: rlsError,
      })
      .mockResolvedValueOnce({
        url: 'https://example.com/item-images/listing-1/0.jpg',
        path: 'listing-1/0.jpg',
        error: null,
      });

    const result = await uploadListingImages('listing-1', 'seller-1', ['file:///photo.jpg']);

    expect(mockUploadImage).toHaveBeenCalledTimes(2);
    expect(mockUploadImage).toHaveBeenNthCalledWith(
      1,
      'item-images',
      'seller-1/listing-1/0.jpg',
      'file:///photo.jpg',
      { upsert: true }
    );
    expect(mockUploadImage).toHaveBeenNthCalledWith(
      2,
      'item-images',
      'listing-1/0.jpg',
      'file:///photo.jpg',
      { upsert: true }
    );
    expect(result).toEqual([
      {
        url: 'https://example.com/item-images/listing-1/0.jpg',
        display_order: 0,
      },
    ]);
  });

  it('cleans up using the actual uploaded path when DB insert fails after fallback upload', async () => {
    const rlsError = new Error('new row violates row-level security policy');
    rlsError.name = 'StorageApiError';

    mockUploadImage
      .mockResolvedValueOnce({
        url: null,
        path: null,
        error: rlsError,
      })
      .mockResolvedValueOnce({
        url: 'https://example.com/item-images/listing-1/0.jpg',
        path: 'listing-1/0.jpg',
        error: null,
      });

    mockSupabase.from = jest.fn((table: string) => {
      if (table === 'admin_config') {
        return {
          select: jest.fn().mockReturnValue({
            eq: jest.fn().mockReturnValue({
              single: jest.fn().mockResolvedValue({
                data: { value: false },
                error: null,
              }),
            }),
          }),
        } as any;
      }

      return {
        insert: jest.fn().mockReturnValue({
          select: jest.fn().mockReturnValue({
            single: jest.fn().mockResolvedValue({
              data: null,
              error: { message: 'insert failed' },
            }),
          }),
        }),
      } as any;
    });

    mockDeleteImage.mockResolvedValue({ error: null });

    await expect(uploadListingImages('listing-1', 'seller-1', ['file:///photo.jpg'])).rejects.toThrow(
      'Failed to save image 1 reference: insert failed'
    );

    expect(mockDeleteImage).toHaveBeenCalledWith('item-images', 'listing-1/0.jpg');
  });
});

import { by, element, expect, device, waitFor } from 'detox';

const RUN_DETOX_E2E = process.env.RUN_DETOX_E2E === 'true';
const describeDetox = describe;

describeDetox('AUTH-008: Forgot Password Flow', () => {
  if (!RUN_DETOX_E2E) {
    it('is activated and requires RUN_DETOX_E2E=true to execute Detox assertions', () => {
      // Intentionally empty: avoids invoking Detox runtime in plain Jest mode.
    });
    return;
  }

  beforeAll(async () => {
    await device.launchApp();
  });

  beforeEach(async () => {
    await device.reloadReactNative();
  });

  describe('Forgot Password Screen', () => {
    it('should navigate to forgot password screen from login', async () => {
      // Navigate to login screen
      await element(by.text('Login Screen')).tap();

      // Tap forgot password link
      await element(by.id('forgot-password-link')).tap();

      // Verify forgot password screen is displayed
      await expect(element(by.text('Forgot Password?'))).toBeVisible();
    });

    it('should show validation error for invalid email', async () => {
      // Navigate to forgot password
      await element(by.text('Login Screen')).tap();
      await element(by.id('forgot-password-link')).tap();

      // Enter invalid email
      await element(by.text('Email Address')).tap();
      await element(by.text('Email Address')).typeText('invalid-email');

      // Try to send reset link
      await element(by.text('Send Reset Link')).tap();

      // Should show alert
      await expect(element(by.text('Invalid Email'))).toBeVisible();
    });

    it('should disable send button when email is empty', async () => {
      // Navigate to forgot password
      await element(by.text('Login Screen')).tap();
      await element(by.id('forgot-password-link')).tap();

      // Send button should be disabled (gray background)
      const sendButton = element(by.text('Send Reset Link'));
      await expect(sendButton).toBeVisible();
    });

    it('should show success screen after sending reset email', async () => {
      // Navigate to forgot password
      await element(by.text('Login Screen')).tap();
      await element(by.id('forgot-password-link')).tap();

      // Enter valid email
      await element(by.text('Email Address')).tap();
      await element(by.text('Email Address')).typeText('test@example.com');

      // Send reset link
      await element(by.text('Send Reset Link')).tap();

      // Should show success screen
      await waitFor(element(by.text('Check Your Email')))
        .toBeVisible()
        .withTimeout(5000);

      await expect(element(by.text('test@example.com'))).toBeVisible();
    });

    it('should allow user to go back to login', async () => {
      // Navigate to forgot password
      await element(by.text('Login Screen')).tap();
      await element(by.id('forgot-password-link')).tap();

      // Tap back to login
      await element(by.text('Back to Login')).tap();

      // Should be back on login screen
      await expect(element(by.text('Login Screen'))).toBeVisible();
    });

    it('should allow resending email from success screen', async () => {
      // Navigate to forgot password and send email
      await element(by.text('Login Screen')).tap();
      await element(by.id('forgot-password-link')).tap();
      await element(by.text('Email Address')).tap();
      await element(by.text('Email Address')).typeText('test@example.com');
      await element(by.text('Send Reset Link')).tap();

      // Wait for success screen
      await waitFor(element(by.text('Check Your Email')))
        .toBeVisible()
        .withTimeout(5000);

      // Tap send another email
      await element(by.text('Send Another Email')).tap();

      // Should be back on forgot password form
      await expect(element(by.text('Forgot Password?'))).toBeVisible();
    });
  });

  describe('Reset Password Screen', () => {
    it('should validate password requirements', async () => {
      // Simulate deep link navigation to reset password
      await device.openURL({ url: 'p2pkidsmarketplace://reset-password' });

      // Wait for screen to load
      await waitFor(element(by.text('Reset Password')))
        .toBeVisible()
        .withTimeout(5000);

      // Enter weak password
      await element(by.text('New Password')).tap();
      await element(by.text('New Password')).typeText('weak');

      // Enter confirm password
      await element(by.text('Confirm Password')).tap();
      await element(by.text('Confirm Password')).typeText('weak');

      // Try to reset
      await element(by.text('Reset Password')).tap();

      // Should show validation error
      await expect(
        element(by.text('Password must be at least 8 characters'))
      ).toBeVisible();
    });

    it('should validate password matching', async () => {
      // Simulate deep link navigation
      await device.openURL({ url: 'p2pkidsmarketplace://reset-password' });

      await waitFor(element(by.text('Reset Password')))
        .toBeVisible()
        .withTimeout(5000);

      // Enter password
      await element(by.text('New Password')).tap();
      await element(by.text('New Password')).typeText('StrongPass123');

      // Enter different confirm password
      await element(by.text('Confirm Password')).tap();
      await element(by.text('Confirm Password')).typeText('DifferentPass123');

      // Try to reset
      await element(by.text('Reset Password')).tap();

      // Should show mismatch error
      await expect(element(by.text('Passwords do not match'))).toBeVisible();
    });

    it('should show password requirements', async () => {
      // Simulate deep link navigation
      await device.openURL({ url: 'p2pkidsmarketplace://reset-password' });

      await waitFor(element(by.text('Reset Password')))
        .toBeVisible()
        .withTimeout(5000);

      // Verify requirements are displayed
      await expect(element(by.text('Password Requirements:'))).toBeVisible();
      await expect(element(by.text('• At least 8 characters'))).toBeVisible();
      await expect(element(by.text('• Contains uppercase letter'))).toBeVisible();
      await expect(element(by.text('• Contains lowercase letter'))).toBeVisible();
      await expect(element(by.text('• Contains number'))).toBeVisible();
    });

    it('should navigate back to login from reset password', async () => {
      // Simulate deep link navigation
      await device.openURL({ url: 'p2pkidsmarketplace://reset-password' });

